############################################################
## 15. Transparently rank descriptive favorable profiles
############################################################

safe_z_score <- function(x) {

  if (
    all(
      !is.finite(
        x
      )
    ) ||
      sd(
        x,
        na.rm = TRUE
      ) == 0
  ) {
    return(
      rep(
        0,
        length(
          x
        )
      )
    )
  }

  as.numeric(
    scale(
      x
    )
  )
}

profile_scored <- profile_summary %>%
  filter(
    N_Accessions >=
      minimum_profile_count
  ) %>%
  group_by(
    Candidate_Interval_ID
  ) %>%
  mutate(
    Z_Rhizome =
      safe_z_score(
        Mean_Rhizome_BLUP
      ),
    Z_Regrowth =
      safe_z_score(
        Mean_Regrowth_BLUP
      ),
    Z_Ancestry_Proxy =
      safe_z_score(
        Mean_Lead_Window_Ancestry_Proxy
      ),
    Descriptive_Profile_Score =
      Z_Rhizome +
      0.5 *
      Z_Regrowth +
      0.5 *
      Z_Ancestry_Proxy
  ) %>%
  ungroup()

favorable_profiles <- profile_scored %>%
  group_by(
    Candidate_Interval_ID
  ) %>%
  slice_max(
    order_by =
      Descriptive_Profile_Score,
    n =
      top_profiles_per_region,
    with_ties =
      FALSE
  ) %>%
  ungroup() %>%
  arrange(
    CHR,
    Candidate_Interval_ID,
    desc(
      Descriptive_Profile_Score
    )
  )

write_csv(
  favorable_profiles,
  file.path(
    out_tables,
    "favorable_haplotype_profiles.csv"
  )
)

############################################################
## 16. Candidate founder-accession ranking
############################################################

candidate_founders <- haplotype_panel %>%
  inner_join(
    favorable_profiles %>%
      select(
        Candidate_Interval_ID,
        Haplotype_Profile,
        Descriptive_Profile_Score
      ),
    by = c(
      "Candidate_Interval_ID",
      "Haplotype_Profile"
    )
  ) %>%
  group_by(
    Accession
  ) %>%
  summarise(
    N_Favorable_Intervals =
      n_distinct(
        Candidate_Interval_ID
      ),
    Favorable_Intervals =
      paste(
        sort(
          unique(
            Candidate_Interval_ID
          )
        ),
        collapse = "; "
      ),
    Mean_Rhizome_BLUP =
      mean(
        Rhiz_BLUP,
        na.rm = TRUE
      ),
    Mean_Regrowth_BLUP =
      mean(
        Regrowth_BLUP,
        na.rm = TRUE
      ),
    Mean_Ancestry_Proxy =
      mean(
        Lead_Window_Ancestry_Proxy,
        na.rm = TRUE
      ),
    Mean_Profile_Score =
      mean(
        Descriptive_Profile_Score,
        na.rm = TRUE
      ),
    .groups =
      "drop"
  ) %>%
  arrange(
    desc(
      N_Favorable_Intervals
    ),
    desc(
      Mean_Rhizome_BLUP
    ),
    desc(
      Mean_Regrowth_BLUP
    ),
    desc(
      Mean_Profile_Score
    )
  ) %>%
  mutate(
    Founder_Rank =
      row_number(),
    .before =
      Accession
  )

write_csv(
  candidate_founders,
  file.path(
    out_tables,
    "candidate_founder_accessions.csv"
  )
)

############################################################
## 17. Lead-SNP effect figure
############################################################

lead_snp_table <- rhizome_intervals %>%
  select(
    CHR,
    Candidate_Interval_ID,
    GWAS_Lead_SNP,
    GWAS_Lead_BP
  )

lead_snp_plot_data <- bind_rows(
  lapply(
    seq_len(
      nrow(
        lead_snp_table
      )
    ),
    function(i) {

      lead_row <- lead_snp_table[
        i,
        ,
        drop = FALSE
      ]

      if (
        !lead_row$GWAS_Lead_SNP %in%
          colnames(
            geno_mat
          )
      ) {
        return(
          NULL
        )
      }

      tibble(
        Accession =
          rownames(
            geno_mat
          ),
        CHR =
          lead_row$CHR,
        Candidate_Interval_ID =
          lead_row$Candidate_Interval_ID,
        Lead_SNP =
          lead_row$GWAS_Lead_SNP,
        Lead_Dosage =
          geno_mat[
            ,
            lead_row$GWAS_Lead_SNP
          ]
      )
    }
  )
) %>%
  left_join(
    analysis_panel %>%
      select(
        Accession,
        Rhiz_BLUP
      ),
    by = "Accession"
  ) %>%
  mutate(
    Rounded_Lead_Dosage =
      factor(
        round_to_step(
          Lead_Dosage,
          dosage_rounding_step
        )
      )
  )

lead_snp_plot <- ggplot(
  lead_snp_plot_data,
  aes(
    x =
      Rounded_Lead_Dosage,
    y =
      Rhiz_BLUP
  )
) +

  geom_boxplot(
    outlier.shape =
      NA
  ) +

  geom_jitter(
    width =
      0.12,
    alpha =
      0.45,
    size =
      1.2
  ) +

  facet_wrap(
    ~Candidate_Interval_ID,
    scales =
      "free_x"
  ) +

  labs(
    title =
      "Rhizome BLUP by GWAS lead-SNP dosage",
    x =
      "Rounded accession-level lead-SNP dosage",
    y =
      "Rhizome BLUP"
  ) +

  theme_classic(
    base_size =
      12
  ) +

  theme(
    plot.title =
      element_text(
        face =
          "bold"
      ),
    strip.text =
      element_text(
        face =
          "bold"
      )
  )

ggsave(
  filename =
    file.path(
      out_figures,
      "Fig_LeadSNP_effects_rhizome.png"
    ),
  plot =
    lead_snp_plot,
  width =
    9,
  height =
    5.5,
  dpi =
    300
)

